From 00b020cfff50fd32bff4c1a6cc349709de80511e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:31:34 +0100
Subject: [PATCH] applet: Offer the dragged Wi-Fi QR code as a PNG file

Dragging the QR code only offered raw image data, so the desktop turned
it into an empty Media Frame. The grabbed image is now also saved as a
PNG in the runtime directory and offered as a file URL to drop targets.

BUG: 509734
---
 applet/ShareNetworkQrCodePage.qml | 9 ++++++++-
 1 file changed, 8 insertions(+), 1 deletion(-)

diff --git a/applet/ShareNetworkQrCodePage.qml b/applet/ShareNetworkQrCodePage.qml
index 09c06f8aa..93f84eaef 100644
--- a/applet/ShareNetworkQrCodePage.qml
+++ b/applet/ShareNetworkQrCodePage.qml
@@ -4,6 +4,7 @@
     SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
 */

+import QtCore
 import QtQuick
 import QtQuick.Layouts

@@ -61,9 +62,15 @@ ColumnLayout {
             onActiveChanged: {
                 if (active) {
                     barcode.grabToImage((result) => {
-                        barcode.Drag.mimeData = {
+                        const fileName = encodeURIComponent(page.ssid.replace(/\//g, "_") + ".png");
+                        const fileUrl = StandardPaths.writableLocation(StandardPaths.RuntimeLocation) + "/" + fileName;
+                        const mimeData = {
                             "image/png": result.image,
                         };
+                        if (result.saveToFile(Qt.url(fileUrl))) {
+                            mimeData["text/uri-list"] = fileUrl;
+                        }
+                        barcode.Drag.mimeData = mimeData;
                         barcode.Drag.active = dragHandler.active;
                     });
                 } else {
